#!/usr/bin/env bash
# Build and run the offline IAUS combat simulator v2 with the host compiler. Host-only, never in the DLL.
# Usage: tools/iaus_sim/run.sh [--list <sim.json>] [--seed N] [--fights N] [--threads N] [--compare <baseline>] [--baseline <out>]
#        [--stealth off|g1|hide|g3] (default g3: every stealth / disengage road of T2 modelled) [--sneak-profile vanilla|steep|list]
#        T2 batch S (iaus-sim-v2.md section 31), every road ON by default:
#        [--t2 off] (every road off + the feet stop = the lab of section 30: 78.11 at g3, 76.69 at --stealth off for --classes beta1)
#        [--feet-stop] [--c8|--dodge|--aversion|--aim|--block|--range|--backoff|--step|--unweighted|--reanimate off|on] [--c13 built|lever]
#        [--disengage-dnd] [--mix-partial] [--aim-miss P] [--aim-scatter P] [--dodge-flight S] [--no-fill-swing] [--teach <token>]
#        Sim batch (iaus-sim-v2.md section 32): [--classes beta1 (12 classes + the 3 tree-OFF base cells) | beta1-tree (the 12)]
#        [--rating N] (fights per cell of the rating battery, default 3; 0 = off) [--rating-only] (the Rating (Tx) table over --seeds, nothing else)
#        [--class-oracle N] [--gap-scenarios N] (the per-class oracle gap; a run that writes a results file runs 4 + 2 by itself, 0 = off)
#        SIM V3 (iaus-sim-v3.md): [--world v2|v3] (default v3, the positional world; v2 = the lab before it, draw for draw)
#        [--v3 height|chase|lof|delivery|hands|stance|sidestep|casterhold|blockdir|areas|perks|hittail|burst=on|off[,...]] [--waiver none|self|player] [--delivery main|old]
#        [--deliver-sec <offense>,<heal>] (a FIXED claim-to-fire; default = the measured tables of Data.h Delivery) [--deliver-unfired <k>] [--mirror on|off] [--engage-on-sight] (ch.21 entry foe modelled; ships OFF) [--block-arc <degrees>] [--scenario field] (the field failures of ClickUp 1dfcuabd44c)
#        [--side-step random|away] (a held caster's side step; off: --v3 sidestep=off) [--caster-pressure] (the caster cells' objective also plays the dive scenarios)
#        [--decline N] (health-decline curves and the best drink line per class) [--curve <class>:<family>.<cons>.<param>=<v>]
#        [--disengage-report N] (card G3's usefulness: the same fights without the run, with it, and with the D&D variant)
#        Class tuning (section 33): [--potion-worth <table>|legacy] [--potion-calib N] [--print-switch] [--guard-why]
#        [--curve <class>:<family>.<cons>.w=<v> | <class>:family.<family>=<v> | <class>:<family>.<cons>.py<i>=<v>]; the run: tools/iaus_sim/tune_driver.py
#        [--steal-lab N] (cards G13 / G14: the witness pre-check against the engine's detection formula)
#        Oracle (iaus-sim-v3.md 14): [--oracle-ceiling N] [--gap-bracket natural|strong1|...] and the diagnostics [--oracle-k N] [--oracle-h S] [--oracle-every S] [--oracle-shared-stream] [--no-class-rulings]
#        Field damage read (section 15): [--damage-report N [--damage-bracket <name>]]; the field side: tools/iaus_sim/calib_damage.py <run-dir> ...
#        SIM V4 batch L, looting in the fight world (iaus-sim-v4.md 14; any of these turns --world v4 on):
#        [--loot-report N [--loot-score]] [--loot-scenario all|<name> [--loot-trace 0]] [--loot-test] [--loot-oracle N] [--loot-cost N]
#        [--loot-plan mixed|stands|walks-on|opens-chest|loots-too|faces-away] [--loot-wave mixed|off|<seconds>] [--loot-sec S] [--loot-guards N]
#        [--loot-list <loot.json> (tools/list_balance/extract_loot.py; with --env-set <set>)] [--loot-museum <share>] [--loot-rule <name>=<v> | gate=old1117]
#        [--env-set <set>/heldout] (the set's held-out places); the field side: tools/iaus_sim/calib_loot.py <run-dir> ...
#   <sim.json> comes from tools/list_balance (extract_world.py -> compile_world.py), default dir ~/.cache/mfo-list-balance/,
#   never committed. Without --list the built-in fixture set runs (no game data).
# SIM_CLITEST=1 runs the command-line assertions (backlog MFO-B710..B714, B755..B757) instead of a run and prints CLI-CHECKS PASS|FAIL.
# SIM_NOBUILD=1 skips the rebuild; SIM_CXXFLAGS adds flags (e.g. -g -fsanitize=address,undefined).
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OUT="${SIM_OUT:-${TMPDIR:-/tmp}/iaus_sim_v2}"
if [[ -z "${SIM_NOBUILD:-}" ]]; then
    # The class table is the game's own: native/classes/ClassTable.cpp compiled with host stand-ins for the engine headers
    # (stub/PCH.h, stub/State.h) and the opcode constants copied out of native/Vocabulary.h (gen_vocab.py), all FIRST on the include path.
    GEN="${OUT}.gen"; mkdir -p "$GEN"
    python3 -I "$ROOT/tools/iaus_sim/gen_vocab.py" "$ROOT/native/Vocabulary.h" "$GEN/Vocabulary.h"
    # RUNTIME CONSTANTS (tune 2.11.1, coordinator 11-13: "any compiled-in constant searched by rebuilding a binary becomes a runtime knob"):
    # a copy of native/iaus in which the four constants the consts stage searches (kCloseSlack, kMinimumFrac, kRangeVeto, kPostureDist) are
    # REFERENCES to sim globals holding native's own literal (read out of the copy here), so `--set const.<name>=<v>` moves them without a
    # rebuild. native/ is never edited; the DLL keeps its constexpr. Each rewrite must hit exactly one initializer or the build stops.
    P="${OUT}.patch"; rm -rf "$P"; mkdir -p "$P/iaus"; cp "$ROOT"/native/iaus/*.h "$ROOT"/native/iaus/*.cpp "$P/iaus/"
    : > "$GEN/simknobs.h"; printf '#pragma once\n#define MFO_SIM_KNOBS 1\n' >> "$GEN/simknobs.h"
    for spec in Reposition.h:kCloseSlack Reposition.h:kMinimumFrac Generate.cpp:kRangeVeto Catalogue.cpp:kPostureDist; do
        F="${spec%%:*}"; N="${spec##*:}"
        n="$(grep -c -E "constexpr float ${N} = [-0-9.]+f;" "$P/iaus/$F" || true)"
        if [[ "$n" != 1 ]]; then echo "run.sh: expected exactly one 'constexpr float $N = <number>f;' in native/iaus/$F, found $n" >&2; exit 2; fi
        V="$(grep -o -E "constexpr float ${N} = [-0-9.]+f;" "$P/iaus/$F" | sed -E 's/.* = ([-0-9.]+f);/\1/')"
        echo "inline float SimKnob_${N} = ${V};" >> "$GEN/simknobs.h"
        sed -i -E "s/(inline )?constexpr float ${N} = [-0-9.]+f;/\1const float\& ${N} = SimKnob_${N};/" "$P/iaus/$F"
    done
    "${CXX:-g++}" -std=c++23 -O2 -pthread -Wall -Wextra -Wno-misleading-indentation -Wno-parentheses ${SIM_CXXFLAGS:-} \
        -DSIM_ENV_DIR="\"${SIM_ENV_DIR:-$ROOT/tools/iaus_sim/envs}\"" -include "$GEN/simknobs.h" -I "$P" -I "$GEN" -I "$ROOT/tools/iaus_sim/stub" -I "$ROOT/native" -I "$ROOT/tools" \
        "$P/iaus/Curves.cpp" "$P/iaus/Catalogue.cpp" "$P/iaus/ClassCurves.cpp" "$P/iaus/Score.cpp" \
        "$P/iaus/Decide.cpp" "$P/iaus/Explain.cpp" "$P/iaus/Generate.cpp" "$P/iaus/EnvQuery.cpp" "$P/iaus/PathSearch.cpp" "$P/iaus/SpellWorth.cpp" \
        "$ROOT/native/classes/ClassTable.cpp" "$ROOT/tools/iaus_sim/RealClasses.cpp" \
        "$ROOT/tools/iaus_sim/sim.cpp" -o "$OUT"
fi
# the results file (Results.h) records where the run came from
export SIM_BRANCH="$(git -C "$ROOT" rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
export SIM_SHA="$(git -C "$ROOT" rev-parse --short HEAD 2>/dev/null || true)"
if [[ -n "${SIM_CLITEST:-}" ]]; then
    fail=0; chk() { if ! eval "$2"; then echo "CLI-CHECK FAILED: $1"; fail=1; fi; }
    R() { "$OUT" --no-json --threads 8 "$@" 2>&1 || true; }
    chk "B710 --fights is honoured and printed" '[[ "$(R --seeds 1,2 --fights 6 --classes mage | tail -1)" == *"fights=6 per scenario"* ]]'
    chk "B710 default is 24 and printed"        '[[ "$(R --seeds 1 --classes mage | tail -1)" == *"fights=24 per scenario"* ]]'
    chk "B711 unknown --classes slug is an error" '! R --classes mage,mgae --seeds 1 | grep -q HEADLINE && R --classes mgae --seeds 1 | grep -q "unknown class"'
    chk "B711 unknown --opt-class is an error"  'R --opt-class mgae --opt x | grep -q "unknown class"'
    chk "B712 JSON headline records its scope"  'J="$(mktemp)"; "$OUT" --classes mage --threads 8 --oracle-ceiling 8 --json "$J" >/dev/null 2>&1; grep -q "\"covers\":\"mage\",\"fights\":24" "$J"; rc=$?; rm -f "$J"; [[ $rc == 0 ]]'
    chk "B713 --opt-prefix honours --seeds"     '[[ "$(R --opt-class mage --opt-prefix --opt-fights 2 --seeds 1,2 | sed -n 2p)" != "$(R --opt-class mage --opt-prefix --opt-fights 2 --seed 1 | sed -n 2p)" ]]'
    chk "B714 --seeds n=1 prints se=n/a"        '[[ "$(R --seeds 1 --classes mage | tail -1)" == *"se=n/a"* ]]'
    chk "B714 --seeds , is an error"            '! R --seeds , | grep -q HEADLINE'
    chk "B755 a full run's headline is 24 fights whatever --fights says" 'J="$(mktemp)"; X="$("$OUT" --classes mage --fights 1 --threads 8 --oracle-ceiling 8 --json "$J" 2>&1)"; grep -q "^HEADLINE  J=.*fights=24 per scenario" <<<"$X"; rc=$?; rm -f "$J"; [[ $rc == 0 ]]'
    chk "B755 --compare refuses a baseline made at another cell size" 'B="$(mktemp)"; R --classes mage --fights 1 --baseline "$B" >/dev/null; X="$(R --classes mage --fights 2 --compare "$B")"; Y="$(R --classes mage --fights 1 --compare "$B")"; rm -f "$B"; [[ "$X" == *"COMPARE REFUSED"* && "$Y" == *"0 metric(s) changed"* ]]'
    chk "B756 the oracle headline records its scope" 'J="$(mktemp)"; "$OUT" --classes mage --fights 1 --threads 8 --headline-oracle 1 --oracle-k 1 --oracle-h 5 --json "$J" >/dev/null 2>&1; grep -q "\"oracle_covers\":\"mage\"" "$J"; rc=$?; rm -f "$J"; [[ $rc == 0 ]]'
    chk "stealth off is the lab before the stealth model (thief, seed 1)" '[[ "$(R --world v2 --t2 off --stealth off --classes thief --seeds 1 --potion-worth legacy | head -1)" == "SEED 1  J=69.13 (scenarios 68.35, natural 69.91)" ]]'   # 69.13 with the sim mirror batch of 11-17 (the reach book of iaus/ReachBook.h, fix/field-1117b-choice's pick rules); 69.12 with --ranged-perks ON by default (part C: the thief's bow carries its own perk chain; --ranged-perks off gives 42.05); 42.05 with batch 3's written values; 42.47 before batch 3 wrote the ranged T1 posture edge (iaus-sim-v2.md 35: the ranged companion)
    chk "T2 batch S: --t2 off is the lab of section 30 at g3 (beta1, seed 1)" '[[ "$(R --world v2 --t2 off --classes beta1-tree --seeds 1 --potion-worth legacy | head -1)" == "SEED 1  J=79.62 (scenarios 82.28, natural 76.96)" ]]'   # 79.62 with sim v4 batch C (the fix/spell-worth mirror: a stream counted for one second, the ask list keeps a refused pair); 79.31 with the sim mirror batch of 11-17 (79.85 with the reach book alone; the rest is fix/field-1117b-choice: heal_rate, the effect-rate tie-break, the line of fire in the pick, the heal safety rule); 79.78 with --ranged-perks ON by default (part C; off: 76.45); 76.45 with batch 3's written values (ranged / archer / evoker / healer posture, section 35); 76.96 in section 30; 76.29 with the School Circle (shipped 2026-11-12, not a T2 road); 76.00 with the Mercenary line in light armor (its card; the kit is not a T2 road either)
    chk "T2 batch S: every road off by name equals --t2 off" '[[ "$(R --feet-stop --c8 off --dodge off --aversion off --aim off --block off --range off --backoff off --step off --c13 lever --unweighted off --reanimate off --classes evoker,knight --seeds 2 | head -1)" == "$(R --t2 off --classes evoker,knight --seeds 2 | head -1)" ]]'
    chk "T2 batch S: --t2 off --roads bash is the lab of section 30 (foe casting is filled; review F1)" '[[ "$(R --world v2 --t2 off --roads bash --classes knight,warrior,mercenary --seeds 1 --potion-worth legacy | head -1)" == "SEED 1  J=80.17 (scenarios 75.56, natural 84.79)" ]]'   # 80.17 with sim v4 batch C (the mage companion's spell reads, as the line above); 80.10 with the sim mirror batch of 11-17 (as the line above); 79.96 with --ranged-perks ON by default (part C); 78.25 with batch 3's written values (the ranged companion); 79.45 in section 30; 79.06 with the School Circle (the Knight scenarios' healer); 78.21 with the Mercenary in light armor
    chk "T2 batch S: the headline names its roads"     '[[ "$(R --classes mage --seeds 1 | tail -1)" == *"t2=all" && "$(R --classes mage --seeds 1 --feet-stop --block off | tail -1)" == *"t2=feet-stop,block=off" ]]'
    chk "T2 batch S: the Knight's table row raises the held guard (MFO-B827)" 'B="$(mktemp)"; R --mode table --classes knight --fights 2 --baseline "$B" >/dev/null; G="$(grep "^knight|natural|guard%=" "$B" | cut -d= -f2)"; rm -f "$B"; awk -v g="$G" "BEGIN { exit !(g > 5) }"'
    chk "T2 batch S: --disengage-report and --steal-lab print their tables" 'R --disengage-report 2 --classes evoker | grep -q "^evoker     dnd" && R --steal-lab 500 | grep -q "^dark "'
    chk "gap stage: --gap-dump prints its lines, only when asked" 'X="$(R --seed 1 --classes knight --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --gap-dump --oracle-subject-only --oracle-k 1 --oracle-h 5)"; Y="$(R --seed 1 --classes knight --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --oracle-k 1 --oracle-h 5)"; [[ "$X" == *"GAPFIGHT knight nat 0 "* && "$X" == *"GAPDEC knight "* && "$X" == *"GAPGEN knight block "* && "$Y" != *GAPFIGHT* ]]'
    chk "logistics world: the model checks pass, a list is refused, the IAUS loot arm runs (it exists since the loot scorer; the older 'refused' clause was stale)" '[[ "$(R --logistics 1 --seeds 1 --classes melee,ranged,mage | tail -1)" == *"=> PASS" ]] && R --logistics 1 --list /nonexistent | grep -q "REFUSED" && R --logistics 1 --logi-policy iaus | grep -q "^LOGIIAUS "'
    chk "class curves: an unknown --curve class / family / param is an error" 'R --classes knight --curve nope:drink_health.need.b=0.9 | grep -q "unknown class" && R --classes knight --curve knight:nope.need.b=0.9 | grep -q "unknown family" && R --classes knight --curve knight:drink_health.need.zz=0.9 | grep -q "unknown curve param"'
    chk "class curves: --curve changes that class's score and no other class's" '[[ "$(R --classes knight --seeds 1 --fights 4 --curve knight:drink_health.need.b=0.9 | head -1)" != "$(R --classes knight --seeds 1 --fights 4 | head -1)" && "$(R --classes mage --seeds 1 --fights 4 --curve knight:drink_health.need.b=0.9 | head -1)" == "$(R --classes mage --seeds 1 --fights 4 | head -1)" ]]'
    chk "class curves: an override equal to the shared value is the baseline" '[[ "$(R --classes knight --seeds 1 --fights 4 --curve knight:scalar.drinkHealthLine=0.34 --curve knight:scalar.touchSpentSec=3 | head -1)" == "$(R --classes knight --seeds 1 --fights 4 | head -1)" ]]'
    chk "sim batch: --opt c.N next to a --curve on consideration N is refused" 'R --classes knight --curve knight:drink_health.32.b=0.5 --opt c.32.b | grep -q "refused" && ! R --classes knight --curve knight:drink_health.32.b=0.5 --opt c.31.b --opt-fights 1 --opt-passes 1 | grep -q "refused"'
    chk "sim batch: the tree-OFF base cells are real cells with their own curve rows" 'R --print-classes | grep -q "melee-off" && [[ "$(R --classes melee-off --seeds 1 --fights 4 --curve melee-off:scalar.touchSpentSec=3 | head -1)" == "$(R --classes melee-off --seeds 1 --fights 4 | head -1)" ]] && [[ "$(R --classes melee-off --seeds 1 --fights 4 --curve melee-off:drink_health.32.b=0.9 | head -1)" != "$(R --classes melee-off --seeds 1 --fights 4 | head -1)" ]] && [[ "$(R --classes melee --seeds 1 --fights 4 --curve melee-off:drink_health.32.b=0.9 | head -1)" == "$(R --classes melee --seeds 1 --fights 4 | head -1)" ]]'
    chk "sim batch: beta1 is the 12 tree-ON classes and the 3 base cells; beta1-tree is the 12" '[[ "$(R --classes beta1 --seeds 1 | tail -1)" == *"warlock,melee-off,ranged-off,mage-off "* && "$(R --classes beta1-tree --seeds 1 | tail -1)" == *"healer,warlock "* ]]'
    chk "sim batch: the rating battery plays the same fights for a tier whatever else runs" 'A="$(R --rating-only --rating 1 --classes knight | awk "\$1==\"knight\"{print \$3}")"; B="$(R --rating-only --rating 1 --classes knight,healer,archer | awk "\$1==\"knight\"{print \$3}")"; [[ -n "$A" && "$A" == "$B" ]]'
    chk "sim batch: a class report run writes the rating, the per-class gap and the ledger slugs (schema 2)" 'J="$(mktemp)"; "$OUT" --classes knight,evoker --fights 1 --threads 8 --class-oracle 1 --gap-scenarios 0 --oracle-k 1 --oracle-h 5 --rating 1 --json "$J" >/dev/null 2>&1; grep -q "^{\"schema\":2" "$J" && grep -q "\"class_gaps\":\[" "$J" && grep -q "{\"class\":\"knight\",\"gap\":" "$J" && grep -q "\"rating\":{\"fights_per_cell\":1" "$J" && grep -q "\"class\":\"knight line\".*\"classes\":\[\"knight\"\]" "$J" && python3 "'"$ROOT"'/tools/iaus_dash/dash.py" --json-check "$J" >/dev/null; rc=$?; rm -f "$J"; [[ $rc == 0 ]]'
    chk "sim batch: the Mercenary line wears light armor (its card) and a heavy cuirass never dodges" 'R --print-classes | grep -q "T2 mercenary .* light" && R --print-classes | grep -q "T2 warrior .* heavy" && [[ "$(R --classes warrior --fights 4 --rating 0 --baseline /dev/stdout | grep "^warrior|natural|dodge/f=" | cut -d= -f2)" == "0" ]]'
    # class tuning (iaus-sim-v2.md section 33). The three exact pins above run with --potion-worth legacy (the older fixed potion rate): they pin the WORLD, not the potion price.
    chk "class tuning: a potion drunk is charged its measured worth (the default differs from the legacy rate; legacy is named in the headline)" '[[ "$(R --classes knight --seeds 1 | head -1)" != "$(R --classes knight --seeds 1 --potion-worth legacy | head -1)" && "$(R --classes knight --seeds 1 --potion-worth legacy | tail -1)" == *"t2=all+potworth=legacy" ]]'
    chk "class tuning: --potion-calib prints the measurement, a missing --potion-worth file is an error" 'R --classes knight --seeds 1 --potion-calib 4 | grep -q "^POTCAL knight 0 4 4 " && R --classes knight --seeds 1 --potion-worth /nonexistent/x | grep -q "cannot read --potion-worth"'
    chk "class tuning: a family weight, a consideration weight and a Piece point are per-class knobs" '[[ "$(R --classes knight --seeds 1 --fights 4 --curve knight:family.attack=1.3 | head -1)" != "$(R --classes knight --seeds 1 --fights 4 | head -1)" && "$(R --classes knight --seeds 1 --fights 4 --curve knight:attack.threat.w=3 | head -1)" != "$(R --classes knight --seeds 1 --fights 4 | head -1)" && "$(R --classes knight --seeds 1 --fights 4 --curve knight:attack.engaged.py0=0.2 | head -1)" != "$(R --classes knight --seeds 1 --fights 4 | head -1)" && "$(R --classes mage --seeds 1 --fights 4 --curve knight:family.attack=1.3 --curve knight:attack.los.py0=0.6 | head -1)" == "$(R --classes mage --seeds 1 --fights 4 | head -1)" ]]'
    chk "class tuning: a family weight of 1 is the baseline; a zero weight, a point on a curve that is not a Piece and an x past its neighbour are refused" '[[ "$(R --classes knight --seeds 1 --fights 4 --curve knight:family.attack=1 | head -1)" == "$(R --classes knight --seeds 1 --fights 4 | head -1)" ]] && R --classes knight --curve knight:family.attack=0 | grep -q "bad weight" && R --classes knight --curve knight:drink_health.need.py0=0.5 | grep -q "unknown curve param" && R --classes knight --curve knight:attack.los.px1=5 | grep -q "unknown curve param"'
    chk "class tuning: --print-switch prints the decision switches per seed; --list-uses prints the Piece points and the families" 'R --classes knight --seeds 1,2 --print-switch | grep -c "^SWITCH " | grep -q "^2$" && R --list-uses | grep -q "^PIECE 0 2 3 " && R --list-uses | grep -q "^FAMILY 0 attack "'
    chk "class tuning: the driver and the potion-worth tool start" 'python3 "'"$ROOT"'/tools/iaus_sim/tune_driver.py" --help >/dev/null && python3 "'"$ROOT"'/tools/iaus_sim/potion_worth.py" --help >/dev/null && python3 "'"$ROOT"'/tools/iaus_sim/edge_search.py" --help >/dev/null'
    chk "class tuning: a list run without its potion-worth table is refused (never the built-in table by default)" 'L="$HOME/.cache/mfo-list-balance/Vanilla.sim.json"; [[ ! -f "$L" ]] || { R --list "$L" --classes knight --seeds 1 --fights 2 | grep -q "needs its own potion-worth table" && R --list "$L" --classes knight --seeds 1 --fights 2 --potion-worth legacy | grep -q "^HEADLINE"; }'
    # SIM V3 (iaus-sim-v3.md): the positional world. --world v2 is v2 draw for draw; the exact pins above run with it.
    chk "sim v3: --world v2 is the shipped v2 baseline, 0 metrics changed" 'R --world v2 --classes beta1 --compare "'"$ROOT"'/tools/iaus_sim/baseline_builtin.txt" | grep -q "^0 metric(s) changed"'
    chk "sim v3: the v3 baseline compares with 0 changes" 'R --classes beta1 --compare "'"$ROOT"'/tools/iaus_sim/baseline_v3_builtin.txt" | grep -q "^0 metric(s) changed"'
    chk "sim v3: the headline names the world, and v2 keeps its own line" '[[ "$(R --classes mage --seeds 1 | tail -1)" == *"stealth=g3  world=v3  t2=all" && "$(R --world v2 --classes mage --seeds 1 | tail -1)" == *"stealth=g3  t2=all" && "$(R --v3 lof=off --waiver self --classes mage --seeds 1 | tail -1)" == *"world=v3(lof=off)+waiver=self  t2=all" ]]'
    chk "sim v3: every switch off by name equals --world v2" '[[ "$(R --v3 height=off,chase=off,lof=off,delivery=off,hands=off,stance=off,sidestep=off,casterhold=off,blockdir=off,areas=off,perks=off,hittail=off,burst=off --classes evoker,knight,archer --seeds 2 | head -1)" == "$(R --world v2 --classes evoker,knight,archer --seeds 2 | head -1)" ]]'
    chk "sim v3: an unknown --world / --v3 switch / --waiver is an error" 'R --world v9 --classes mage --seeds 1 | grep -q "world v2|v3" && R --v3 nope=off --classes mage --seeds 1 | grep -q "unknown --v3 switch" && R --waiver nope | grep -q "waiver none|self|player"'
    chk "sim v3: the field scenarios run by name, and are not part of the headline" 'R --scenario field --fights 2 | grep -q "^jesper-dagger" && ! R --scenario all --fights 1 | grep -q "^jesper-dagger"'
    chk "sim v3: the chase cap drops a circling dragon without the waiver, and never in v2" 'A="$(R --scenario dragon-circle --fights 16 --waiver none | grep -A1 "cap.drop%" | tail -1 | awk "{print \$2}")"; B="$(R --scenario dragon-circle --fights 16 --world v2 | grep -A1 "cap.drop%" | tail -1 | awk "{print \$2}")"; awk -v a="$A" -v b="$B" "BEGIN { exit !(a > 5 && b == 0) }"'
    chk "sim v3: a cast through a friend is held, and not every chosen cast fires" 'X="$(R --scenario fire-lane --fights 16 | grep -A1 "dl.fired%" | tail -1)"; awk -v f="$(echo "$X" | awk "{print \$2}")" -v h="$(echo "$X" | awk "{print \$4}")" "BEGIN { exit !(f < 99 && h > 1) }"'
    # sim mirror batch 11-17 (iaus-sim-v3.md 13)
    chk "sim mirror: --mirror off and --deliver-unfired are named in the headline and move the score" '[[ "$(R --classes evoker --seeds 1 --mirror off --deliver-unfired 0 | tail -1)" == *"world=v3+mirror=off+deliver-unfired  t2=all" && "$(R --classes evoker --seeds 1 --deliver-unfired 0 | head -1)" != "$(R --classes evoker --seeds 1 | head -1)" && "$(R --classes evoker --seeds 1 --deliver-sec 2.4,4.5 | tail -1)" == *"+deliver-sec  t2=all" ]]'
    chk "sim mirror: the blade climbs a tower with a stair (the 128 approach), and never hits it without the mirror" 'A="$(R --scenario tower-blade --fights 16 | grep -A1 "nohit%" | tail -1 | awk "{print \$3}")"; B="$(R --scenario tower-blade --fights 16 --mirror off | grep -A1 "nohit%" | tail -1 | awk "{print \$3}")"; awk -v a="$A" -v b="$B" "BEGIN { exit !(a < 20 && b > 95) }"'
    chk "sim mirror: a bow follower shot from past his chase cap keeps those foes (noApproach) and is not left with an empty foe list" 'A="$(R --scenario cap-archer --fights 16 | grep -A1 "cap.kept/f" | tail -1)"; B="$(R --scenario cap-archer --fights 16 --mirror off | grep -A1 "cap.kept/f" | tail -1)"; awk -v k="$(echo "$A" | awk "{print \$7}")" -v s="$(echo "$A" | awk "{print \$8}")" -v s0="$(echo "$B" | awk "{print \$8}")" "BEGIN { exit !(k > 1 && s < s0 - 20) }"'
    chk "sim mirror: the new tuning scalars are knobs, and the cast-delay tool starts" '[[ "$(R --list-params)" == *"t.concChannelSec t.handRedrawSec t.waivedRangeX t.bowRange t.spellCastSec t.dyingSelfHp t.fireLineKeepSec"* ]] && R --classes archer --seeds 1 --fights 2 --set t.bowRange=100,t.waivedRangeX=0.5 | grep -q "^HEADLINE" && [[ "$(python3 "'"$ROOT"'/tools/iaus_sim/calib_cast_delay.py" 2>&1 || true)" == *"READ-ONLY"* ]]'
    # oracle fix round + field damage read (iaus-sim-v3.md 14, 15)
    chk "oracle: the gap pass prints its stop line and the class filter's refusals, and a tree-ON warrior has no guard and no sprint away" 'X="$(R --seed 1 --classes warrior --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --oracle-ceiling 8)"; [[ "$X" == *"ORCSTOP warrior decisions "* && "$X" == *"ext:block:class has no Block row"* && "$X" == *"ext:sprint_back:class has no disengage"* ]]'
    chk "oracle: the per-actor streams are named when off, and an unknown --gap-bracket is an error" '[[ "$(R --seed 1 --classes thief --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --oracle-ceiling 8 --oracle-shared-stream)" == *"DIAGNOSTIC one shared random stream"* ]] && R --gap-bracket nope --classes thief | grep -q "unknown --gap-bracket" && R --seed 1 --classes thief --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --oracle-ceiling 8 --gap-bracket strong1 | grep -q "^GAP BRACKET strong1"'
    chk "field damage: --damage-report prints the sense, downs, burst and who lines; the field tool starts" 'X="$(R --classes melee,mage --seeds 1 --damage-report 4 --damage-bracket strong1)"; [[ "$X" == *"SIM SENSE ALL "* && "$X" == *"SIM DOWNS ALL "* && "$X" == *"SIM BURST ALL "* && "$X" == *"SIM WHO   ALL "* && "$X" == *"4 strong1 fights"* ]] && [[ "$(python3 "'"$ROOT"'/tools/iaus_sim/calib_damage.py" 2>&1 || true)" == *"READ-ONLY"* ]]'
    # sim v4 slice 1 (iaus-sim-v4.md 9)
    chk "sim v4: the heal-timing mirror (burst) makes the game's knobs live, and they are flat without it" '[[ "$(R --list-params)" == *"t.dyingAllyHp t.dyingHitsToDown t.urgencyHitsDiv t.grossWindowSec t.maxHitWindowSec t.burstWindowSec"* ]] && A="$(R --classes healer,evoker --seeds 1 | head -1)" && B="$(R --classes healer,evoker --seeds 1 --set t.dyingHitsToDown=3,t.urgencyHitsDiv=8 | head -1)" && C="$(R --classes healer,evoker --seeds 1 --v3 burst=off | head -1)" && D="$(R --classes healer,evoker --seeds 1 --v3 burst=off --set t.dyingHitsToDown=3,t.urgencyHitsDiv=8 | head -1)" && [[ "$A" != "$B" && "$A" != "$C" && "$C" == "$D" ]]'
    chk "sim v4: review F-B / F-C: hittail alone tags the world v3; ORCSTOP / ORCREFUSED count the subject only (a warrior is refused the guard once per decision of HIS)" '[[ "$(R --world v2 --v3 hittail=on --classes mage --seeds 1 | tail -1)" == *"world=v3("* ]] && X="$(R --seed 1 --classes warrior --fights 1 --rating 0 --class-oracle 2 --gap-scenarios 0 --oracle-ceiling 8)" && A="$(echo "$X" | grep "^ORCSTOP warrior" | sed -E "s/.*decisions ([0-9]+).*/\1/")" && B="$(echo "$X" | grep "^ORCREFUSED warrior .* ext:block:class has no Block row" | cut -d" " -f3)" && [[ -n "$A" && "$A" == "$B" ]]'
    chk "sim v4: the live tools (round runner, priority table, class-file generator) pass their tests" 'python3 -W ignore "'"$ROOT"'/tools/iaus_sim/live/test_live.py" >/dev/null 2>&1 && python3 "'"$ROOT"'/tools/iaus_sim/live/priority.py" --levels | grep -q "^idle .*CPUWeight=idle IOWeight=1 .*default"'
    # sim v4 batch W (iaus-sim-v4.md 1, 2, 5): the environment world. --world v3 stays the default and its baseline check is above.
    FX="$ROOT/tools/iaus_sim/envs"
    chk "sim v4 world: the hand-made fixtures are what their .txt says, and the known-answer environment checks pass" 'python3 "$FX/make_fixtures.py" --check >/dev/null && R --env-test | grep -q "^ENV-TESTS PASS: 81 checks, 0 failed"'
    chk "sim v4 world: the v4 baseline compares with 0 changes" 'R --world v4 --classes beta1 --compare "'"$ROOT"'/tools/iaus_sim/baseline_v4_builtin.txt" | grep -q "^0 metric(s) changed"'
    chk "sim v4 world: the headline names the world and its places; every v4 switch off by name is --world v3" '[[ "$(R --world v4 --classes mage --seeds 1 | tail -1)" == *"world=v4+env=fixtures#"*"  t2=all" && "$(R --world v4 --v4 drops=on --sight terrain=off --seats old --classes mage --seeds 1 | tail -1)" == *"world=v4[drops=on]+env=fixtures#"*"+seats=old+sight=terrain=off  t2=all" ]] && [[ "$(R --world v4 --v4 env=off,path=off,bodies=off,los=off,caststart=off,interrupt=off --classes evoker,knight,archer --seeds 2 | head -1)" == "$(R --world v3 --classes evoker,knight,archer --seeds 2 | head -1)" ]]'
    chk "sim v4 world: an unknown --v4 switch / --sight / --seats / --env is an error, and an environment scenario needs the world" 'R --v4 nope=on --classes mage --seeds 1 | grep -q "unknown --v4 switch" && R --world v4 --sight nope | grep -q "sight walls=off" && R --world v4 --seats nope | grep -q "seats today|old" && R --world v4 --seat-immunity nope | grep -q "seat-immunity seen|unseen" && R --world v4 --env /nonexistent.mfoenv --classes mage --seeds 1 | grep -q "^--env /nonexistent" && R --scenario env-island --fights 1 | grep -q "needs an environment"'
    chk "sim v4 world: the same run at 1 thread and at 16 (the route cache is keyed centroid to centroid)" '[[ "$("$OUT" --no-json --threads 1 --world v4 --classes knight,evoker,healer --seeds 3 2>&1 | head -1)" == "$("$OUT" --no-json --threads 16 --world v4 --classes knight,evoker,healer --seeds 3 2>&1 | head -1)" ]]'
    chk "sim v4 world: a blade reaches a tower top by its ramp, is pinned under a floor nothing joins (the field case, measured), and pushes at a wall the mesh does not know" 'X="$(R --world v4 --scenario env-tower-stairs,env-island,trust-ignored-wall --fights 8)"; A="$(echo "$X" | grep -A2 "^env-tower-stairs" | tail -1 | awk "{print \$3}")"; B="$(echo "$X" | grep -A2 "^env-island" | tail -1 | awk "{print \$2, \$5}")"; C="$(echo "$X" | grep -A2 "^trust-ignored-wall" | tail -1 | awk "{print \$2}")"; awk -v a="$A" -v b="$B" -v c="$C" "BEGIN { split(b, q, \" \"); exit !(a < 20 && q[1] > 60 && q[2] > 60 && c > 20) }"'
    chk "sim v4 world: the pathing gate prints its cells, counts no off-mesh body and no follower stuck for good, and --path-gate is the exit code" 'X="$(R --world v4 --path-report 4 --classes knight,archer --path-gate)"; [[ "$X" == *"PATH GATES: 14 cell(s)"* && "$X" == *"env.bad 0 (must be 0)  stuck forever 0 (must be 0)"* && "$X" == *"holdUnr.s     hold%  repeat/f"* ]] && R --path-report 2 | grep -q "needs an environment"'
    # review F9: the gate with --path-oracle K reads IAUS on the K fights the oracle also played. The first fight of a cell is the same fight whatever N is,
    # so the ORCPATH lines of (N 3, K 1) and of (N 1, K 1) must be the same lines, and there is one per cell and gate row (7 places classes x 8 rows).
    chk "sim v4 world: with --path-oracle the gate compares IAUS and the oracle on the SAME fights, one ORCPATH line per cell and gate row (review F9)" 'A="$(R --world v4 --path-report 3 --path-oracle 1 --classes knight --oracle-ceiling 8 | grep "^ORCPATH")"; B="$(R --world v4 --path-report 1 --path-oracle 1 --classes knight --oracle-ceiling 8 | grep "^ORCPATH")"; [[ -n "$A" && "$A" == "$B" && "$(echo "$A" | wc -l)" == 56 && "$A" == *" hold% "*" repeat/f "* ]]'
    # review F4 + the adopt-seats mirror (native cast/SeatRows.h): a held-off spell costs the decision that picked it; --seats old refuses the Paralyze /
    # TargetEffect rows outright and today's game does not; today a spell fired into an immunity nobody can read is counted, and --seat-immunity seen ends that.
    chk "sim v4 world: a held-off spell costs the turn; --seats old refuses the rows ABI 46 seats; a fire that leaves nothing is counted (review F4, adopt-seats)" 'T="$(mktemp -d)"; R --world v4 --seats old --classes beta1 --baseline "$T/old" >/dev/null; R --world v4 --classes beta1 --baseline "$T/new" >/dev/null; R --world v4 --seat-immunity seen --classes beta1 --baseline "$T/seen" >/dev/null; nz() { grep -E "\\|$2=" "$1" | awk -F= "\$2 + 0 > 0" | wc -l; }; a="$(nz "$T/old" cs.heldTurns/f)"; b="$(nz "$T/old" cs.unseated/f)"; c="$(nz "$T/new" cs.unseated/f)"; d="$(nz "$T/new" cs.zeroFire/f)"; e="$(nz "$T/old" cs.zeroFire/f)"; f="$(nz "$T/seen" cs.zeroFire/f)"; g="$(nz "$T/new" cs.heldTurns/f)"; rm -rf "$T"; [[ "$a" -gt 0 && "$b" -gt 0 && "$c" == 0 && "$d" -gt 0 && "$e" == 0 && "$f" -lt "$d" && "$g" -gt 0 ]]'
    chk "sim v4 world: the solo walk on the fixtures: every trip with a route ends AT its goal, its height included (review F1)" 'R --solo-walk 60 | grep -q "WRONG 0 (0.000%), of them over or under the goal 0  off-mesh steps 0  => PASS"'
    # SIM V4 BATCH L (iaus-sim-v4.md 14): looting in the fight world
    chk "sim v4 loot: the loot fixtures are what their .txt says" 'python3 "$FX/make_fixtures.py" --check loot-room loot-backs loot-freeze loot-gate loot-town loot-shop loot-watch >/dev/null'
    chk "sim v4 loot: the 24 scenarios hold (three of them reproduce a fault of the builds before efd097dc)" 'R --loot-test | grep -q "^LOOT-TESTS PASS: 24 scenarios, 0 failed (3 of them reproduce a fault of the builds before efd097dc)"'
    chk "sim v4 loot: the old faults' leg counts stand under the older build (27, 25, 15), and the pass lift is the only lift of gate-pass-real" 'X="$(R --loot-test)"; grep -A3 "^LOOT-SCENARIO stall-same-item" <<<"$X" | grep -q "variant: .* legs 27" && grep -A3 "^LOOT-SCENARIO locked-door-cycle" <<<"$X" | grep -q "today: .* legs 25" && grep -A3 "^LOOT-SCENARIO carry-full" <<<"$X" | grep -q "today: .* legs 15" && R --loot-scenario gate-pass-real | grep -q "^LOOTRATE today .*the player walked through the block point"'
    chk "sim v4 loot: the 11-17g freeze fails the gate under the old rule and not under today's (leftRR/ep)" 'X="$(R --loot-scenario freeze-1117g)"; grep -q "^LOOTGATE today  *leftRR/ep .* ok$" <<<"$X" && grep -q "^LOOTGATE variant  *leftRR/ep .* FAIL$" <<<"$X"'
    chk "sim v4 loot: no scenario under the lab's rules and no report counts a crime or a take a guard saw, and the one variant that must commit a crime does (thief-no-recheck, review S1)" '! R --loot-scenario all | grep -E "^LOOTGATE today .* (crimes|guardSeenTakes) " | grep -q FAIL && [[ "$(R --loot-scenario all | grep -E "^LOOTGATE variant .* (crimes|guardSeenTakes) " | grep -c FAIL)" == 2 ]] && R --loot-scenario thief-no-recheck | grep -Eq "^LOOTGATE variant +crimes .* FAIL$" && ! R --loot-report 2 --seeds 1,2 | grep -E "^LOOTGATE ALL .* (crimes|guardSeenTakes) " | grep -q FAIL'
    chk "sim v4 loot: a table that ignores loot (takeThreshold 1) fails MORE gate rows than the shipped one, leftRR/ep and roadLeft% among them (review: the gate must not be passable by taking less)" 'A="$(R --classes beta1 --loot-report 8 --seeds 1,2,3,4 | grep "^LOOTGATE ALL")"; B="$(R --classes beta1 --loot-report 8 --seeds 1,2,3,4 --set loot.takeThreshold=1.0 | grep "^LOOTGATE ALL")"; grep -Eq "leftRR/ep .* ok$" <<<"$A" && grep -Eq "roadLeft% .* ok$" <<<"$A" && grep -Eq " leftRR/ep .* FAIL$" <<<"$B" && grep -Eq "roadLeft% .* FAIL$" <<<"$B" && (( $(grep -c "FAIL$" <<<"$B") > $(grep -c "FAIL$" <<<"$A") ))'
    chk "sim v4 loot: a report is the same at 1 thread and at 8" '[[ "$("$OUT" --no-json --threads 1 --loot-report 2 --seeds 1,2 2>&1 | grep "^LOOT ALL")" == "$(R --loot-report 2 --seeds 1,2 | grep "^LOOT ALL")" ]]'
    chk "sim v4 loot: the oracle is never under the game, and --loot-score prints the driver's SEED lines" 'R --loot-oracle 1 --seeds 1 --classes melee | grep -q "^ORCLOOT melee" && R --loot-oracle 1 --seeds 1,2 --classes melee,ranged | awk "/^ORCLOOT (melee|ranged)/ { if (\$5 < -0.0005) bad = 1 } END { exit bad }" && [[ "$(R --loot-report 1 --loot-score --seeds 3,4 --classes melee | grep -c "^SEED ")" == 2 ]]'
    chk "sim v4 loot: an unknown rule or scenario is an error" 'R --loot-rule nosuch=1 --loot-test | grep -q "unknown rule" && R --loot-scenario nosuch | grep -q "unknown loot scenario"'
    chk "sim v4 world: a compare across two sets of places is refused (the library hash is in the world tag)" 'R --world v4 --env "$FX/open-room.mfoenv" --classes beta1 --compare "'"$ROOT"'/tools/iaus_sim/baseline_v4_builtin.txt" | grep -q "COMPARE REFUSED"'
    # needs the extracted library (never in git): MFO_ENV_CACHE, default ~/.cache/mfo-env. Without it the check says so and passes.
    LIB="${MFO_ENV_CACHE:-$HOME/.cache/mfo-env}"
    if [[ -f "$LIB/index.json" ]]; then
        chk "sim v4 world: the solo walk over the whole library: under a tenth of a percent of trips end anywhere but their goal, none off the mesh" 'R --solo-walk 170 --env-set all | grep -q "^SOLO-WALK  .*=> PASS"'
    else echo "CLI-CHECK SKIPPED (no library at $LIB; set MFO_ENV_CACHE): the solo walk over the whole library"; fi
    chk "sim v4: the field-rate tool for the pathing numbers starts" 'python3 "'"$ROOT"'/tools/iaus_sim/calib_path.py" --help >/dev/null'
    # needs the saved field logs (never in git): SIM_EVIDENCE, default <repo>/_evidence. Without them the check says so and passes.
    EV="${SIM_EVIDENCE:-$ROOT/_evidence}"
    if [[ -d "$EV/deck-run-1117f" && -d "$EV/deck-run-1119-jesper" ]]; then
        chk "sim v4: calib_damage.py reproduces World.h kFieldHit and World.h kOneHitLine from the five probe sessions" 'X="$(python3 "'"$ROOT"'/tools/iaus_sim/calib_damage.py" "$EV/deck-run-1117c" "$EV/deck-run-1117f" "$EV/deck-run-1117g" "$EV/deck-run-1118-adelinda" "$EV/deck-run-1119-jesper")"; ROW="$(echo "$X" | grep "^kFieldHit\[" | sed -E "s/.*= (\{.*\});/\1/")"; grep -qF "kFieldHit[] = $ROW;" "'"$ROOT"'/tools/iaus_sim/World.h" && [[ "$X" == *"FIELD HIT WINDOWS n=139 over 5 session(s)"*"p90 34.5%"* ]] && grep -q "kOneHitLine = 0.35f" "'"$ROOT"'/tools/iaus_sim/World.h"'
    else echo "CLI-CHECK SKIPPED (no field logs at $EV; set SIM_EVIDENCE): calib_damage.py reproduces kFieldHit / kOneHitLine"; fi
    # sim v4 batch C (iaus-sim-v4.md 15): the spell-worth mirror, field-size books, the regret report, the IAUS arm of a gap fight
    G1=(--seed 1 --classes evoker --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --gap-dump --oracle-subject-only --oracle-k 1 --oracle-h 5)
    chk "batch C: the spell rules and the books are named in the headline; an unknown value of either, of --env-hold, --gap-arm or --oracle-prune is an error; t.unmeasuredDamage is a knob" '[[ "$(R --classes mage --seeds 1 --spell-rules old --books field | tail -1)" == *"world=v3+spell-rules=old+books=field  t2=all" && "$(R --classes mage --seeds 1 --books heldout | tail -1)" == *"+books=heldout  t2=all" ]] && R --spell-rules nope | grep -q "spell-rules today|old|all" && R --books nope | grep -q "books lab|field|heldout" && R --env-hold nope | grep -q "env-hold all|train|heldout" && R --gap-arm nope | grep -q "gap-arm both|iaus" && R --oracle-prune nope | grep -q "oracle-prune on|off" && [[ "$(R --list-params)" == *" t.unmeasuredDamage"* ]] && R --classes evoker --seeds 1 --fights 2 --set t.unmeasuredDamage=0.25 | grep -q "^HEADLINE"'
    chk "batch C: the regret report rides the gap pass, one extra SPELLFIGHT column per alternate table, and only when asked" 'X="$(R "${G1[@]}" --spell-regret --regret-alt t.unmeasuredDamage=0.25 --regret-alt aw.9=3)"; Y="$(R "${G1[@]}")"; [[ "$(echo "$X" | grep -c "^SPELLFIGHT evoker nat 0 [0-9]* [-0-9.]* [-0-9.]* [-0-9.]*$")" == 1 && "$X" == *"SPELLDEC evoker "* && "$X" == *"SPELL REGRET (rules today, books lab"* && "$Y" != *"SPELLFIGHT"* && "$Y" != *"SPELL REGRET"* ]] && R "${G1[@]}" --regret-alt aw.9=3 | grep -q "needs --spell-regret"'
    chk "batch C: the IAUS arm alone is the gap fight's own IAUS fight (the same U), with no oracle line" 'X="$(R "${G1[@]}" | grep "^GAPFIGHT evoker nat 0 " | awk "{print \$5}")"; Y="$(R "${G1[@]}" --gap-arm iaus)"; [[ -n "$X" && "$(echo "$Y" | grep "^GAPIAUS evoker nat 0 " | awk "{print \$5}")" == "$X" && "$Y" != *"GAPFIGHT"* && "$Y" != *"CLASS ORACLE GAP"* ]]'
    chk "batch C: the driver tests pass (follow, spells, the regret readers, the SpellWorth rows)" 'python3 -W ignore -I "'"$ROOT"'/tools/iaus_sim/test_tune_driver.py" >/dev/null 2>&1'
    L="$HOME/.cache/mfo-list-balance/Tuxborn.sim.json"
    if [[ -f "$L" ]]; then
        # THE FIELD'S FAILURE, reproduced and fixed (field 11-23, _agentlogs/mfo/diag-spell-choice.md): with the rules of that build an offense spell IAUS
        # cannot measure is on top of the list in a large share of the spell laps and some of them tie to the last digit; with today's rules it is rare
        # and none tie. And a field book is many times the lab's.
        chk "batch C: on a list world with field-size books the old rules put unmeasured spells on top and tie them, and today's rules do not" 'T="$(mktemp -d)"; for r in old today; do R --list "$L" --potion-worth legacy --classes evoker,mage --seed 1 --books field --spell-rules $r --baseline "$T/$r" >/dev/null; done; g() { grep "^$2|natural|$3=" "$T/$1" | cut -d= -f2; }; ok=1; for c in evoker mage; do awk -v a="$(g old $c sp.unmTop%)" -v b="$(g today $c sp.unmTop%)" -v t="$(g old $c sp.tie%)" -v u="$(g today $c sp.tie%)" "BEGIN { exit !(a > 20 && b < 5 && t > 1 && u == 0) }" || ok=0; done; rm -rf "$T"; [[ $ok == 1 ]]'
    else echo "CLI-CHECK SKIPPED (no list world at $L): the old and today's spell rules on field-size books"; fi
    # sim v4 batch C (iaus-sim-v4.md 15.7): the race's cost cuts say what they are and are off unless asked for (their effect is oracle_replay.py's to measure)
    chk "batch C: the oracle race's cuts are named in the header, run fewer rollouts a decision, and the default race is the full one" 'G="--seed 1 --classes mage --fights 1 --rating 0 --class-oracle 1 --gap-scenarios 0 --oracle-ceiling 16"; A="$(R $G)"; B="$(R $G --oracle-prune target --oracle-pair 0.10 --oracle-nmin 4)"; [[ "$B" == *"from 4, ceiling 16"*"pairwise indifference 0.10 U, dominance on the foe"* && "$B" == *"retired by the pair rule"* && "$A" != *"pairwise indifference"* && "$A" != *"retired by the pair rule"* && "$A" == *"from 8, ceiling 16"* ]] && [[ "$(R $G --oracle-prune maybe)" == *"--oracle-prune on|off|target"* ]]'
    chk "an unknown --sneak-profile is an error"  'R --sneak-profile nope --classes mage --seeds 1 | grep -q "unknown --sneak-profile"'
    if [[ $fail == 0 ]]; then echo "CLI-CHECKS PASS"; exit 0; else echo "CLI-CHECKS FAIL"; exit 1; fi
fi
exec "$OUT" "$@"
